/**
 * Public, human-friendly aliases over the generated OpenAPI types in `api.d.ts`.
 *
 * This file is hand-written; `api.d.ts` is generated by `npm run contracts` and must
 * never be edited directly. Import API shapes from `@aab/contracts` in the web app so
 * a schema change fails the type-check instead of silently drifting.
 */
export type { components, operations, paths } from "./api.js";

import type { components } from "./api.js";

type S = components["schemas"];

export type Health = S["Health"];
export type BookSummary = S["BookSummary"];
