export type RenderRequest = S["RenderRequest"];
export type RenderPending = S["RenderPending"];
export type ManifestSegment = S["ManifestSegment"];
export type ChapterManifest = S["ChapterManifest"];
export type JobStatus = S["JobStatus"];
export type Credentials = S["Credentials"];
export type UserOut = S["UserOut"];
export type TokenPair = S["TokenPair"];
export type LibraryPage = S["LibraryPage"];
export type LibraryItem = S["LibraryItem"];
export type LibraryEntry = S["LibraryEntry"];
export type ProgressUpdate = S["ProgressUpdate"];
export type ProgressState = S["ProgressState"];
export type BookProgress = S["BookProgress"];
export type AdminJob = S["AdminJob"];
export type AdminJobPage = S["AdminJobPage"];
export type AdminJobDetail = S["AdminJobDetail"];
export type AdminWork = S["AdminWork"];
